-- County-level quarterly and annual employment and wage statistics by industry (NAICS) and ownership sector, derived from unemployment insurance tax records.
-- Auto-generated by scripts/gen_evidence_pages.py: 3,619,437 rows > 100k, so this is a BOUNDED pre-aggregate (parquet-safe by construction), not select *.
-- grouped on year-like text/number column YEAR (NOT date-cast -- avoids the 8-digit epoch trap); LIMIT bounds it.
select "YEAR" as year, count(*) as records
from THE_LIBRARY.ECONOMY.FED_BLS_QCEW
group by 1
order by 1
limit 1000
